/**
 * Kiro Crew app bundle helpers (`lib/chimera/crew-bundle.ts`).
 *
 * The app's files are embedded in `crew-app-files.ts` (generated by
 * `scripts/embed-crew-app.mjs`), so the download button works in Studio Hub and in exported
 * projects alike. These helpers validate the files with the App Kit rules and pack them into a
 * zip that `kirocrew app install` can use after extraction.
 */

import JSZip from "jszip";
import { CREW_APP_FILES, type CrewTextFile } from "./crew-app-files.js";
import { validateCrewBundle, type CrewAgent, type CrewManifest, type CrewValidation } from "./crew-manifest.js";

export { CREW_APP_FILES, type CrewTextFile };

export const CREW_APP_PREFIX = "kiro-crew-app/";
export const CREW_APP_FOLDER = "chimera-lab";
export const CREW_APP_ZIP_NAME = "chimera-lab-kiro-crew-app.zip";

export interface SourceFileLike {
  readonly path: string;
  readonly content: string;
  readonly encoding?: "utf8" | "base64";
}

/**
 * The Python hooks as template-relative source files. The shared bundler skips `.py`, so the
 * template entry appends these to its source files for the Next.js export.
 */
export const CREW_PYTHON_SOURCE_FILES: readonly CrewTextFile[] = CREW_APP_FILES.filter((f) => f.path.endsWith(".py")).map((f) => ({
  path: `${CREW_APP_PREFIX}${f.path}`,
  content: f.content,
}));

/** App-relative files (`app.json`, `agents/…`) found in a template source bundle, in code-point order. */
export function collectCrewAppFiles(sourceFiles: readonly SourceFileLike[]): CrewTextFile[] {
  const byPath = new Map<string, string>();
  for (const file of sourceFiles) {
    if (!file.path.startsWith(CREW_APP_PREFIX) || file.encoding === "base64") continue;
    byPath.set(file.path.slice(CREW_APP_PREFIX.length), file.content.replace(/\r\n/g, "\n"));
  }
  return [...byPath.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([path, content]) => ({ path, content }));
}

export function validateCrewAppFiles(files: readonly CrewTextFile[]): CrewValidation<{ manifest: CrewManifest; agents: CrewAgent[] }> {
  const encoder = new TextEncoder();
  return validateCrewBundle(Object.fromEntries(files.map((f) => [f.path, encoder.encode(f.content)])));
}

/** Zip the app under `chimera-lab/` so it extracts to an installable folder. */
export async function buildCrewAppZip(files: readonly CrewTextFile[] = CREW_APP_FILES): Promise<Uint8Array> {
  const zip = new JSZip();
  const folder = zip.folder(CREW_APP_FOLDER)!;
  for (const file of files) folder.file(file.path, file.content);
  return zip.generateAsync({ type: "uint8array", compression: "DEFLATE" });
}
